CREATE SCHEMA IF NOT EXISTS linkdid;
REVOKE ALL ON SCHEMA linkdid FROM PUBLIC, anon, authenticated;
CREATE TABLE linkdid.profiles (id text PRIMARY KEY,owner text NOT NULL UNIQUE,name text NOT NULL,headline text NOT NULL,url text NOT NULL UNIQUE,category text NOT NULL,location text NOT NULL DEFAULT '',photo text,created bigint NOT NULL);
CREATE TABLE linkdid.gas_tanks (profile text PRIMARY KEY REFERENCES linkdid.profiles(id),free bigint NOT NULL DEFAULT 0 CHECK(free>=0),paid bigint NOT NULL DEFAULT 0 CHECK(paid>=0),updated bigint NOT NULL,progress bigint NOT NULL DEFAULT 0 CHECK(progress>=0 AND progress<60000),pulse bigint NOT NULL DEFAULT 0,session text,sequence bigint NOT NULL DEFAULT 0);
CREATE TABLE linkdid.metrics (id text PRIMARY KEY,profile text NOT NULL REFERENCES linkdid.profiles(id),viewer text NOT NULL,kind text NOT NULL CHECK(kind IN ('view','click')),day text NOT NULL,UNIQUE(profile,viewer,kind,day));
CREATE TABLE linkdid.notifications (id text PRIMARY KEY,owner text NOT NULL,message text NOT NULL,created bigint NOT NULL,read integer NOT NULL DEFAULT 0);
CREATE TABLE linkdid.bids (id text PRIMARY KEY,profile text NOT NULL REFERENCES linkdid.profiles(id),owner text NOT NULL,amount bigint NOT NULL,created bigint NOT NULL,mode text NOT NULL DEFAULT 'sandbox');
CREATE TABLE linkdid.orders (id text PRIMARY KEY,owner text NOT NULL,profile text NOT NULL REFERENCES linkdid.profiles(id),amount bigint NOT NULL,currency text NOT NULL,provider text UNIQUE,status text NOT NULL DEFAULT 'creating',details text,created bigint NOT NULL,checked bigint NOT NULL DEFAULT 0,gas_litres bigint NOT NULL DEFAULT 0);
CREATE TABLE linkdid.paid_bids (id text PRIMARY KEY REFERENCES linkdid.orders(id),profile text NOT NULL REFERENCES linkdid.profiles(id),amount bigint NOT NULL,created bigint NOT NULL);
CREATE TABLE linkdid.tickets (id text PRIMARY KEY,owner text NOT NULL,subject text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'open',created bigint NOT NULL);
CREATE TABLE linkdid.claims (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request text NOT NULL UNIQUE,profile text NOT NULL REFERENCES linkdid.profiles(id),started bigint NOT NULL,expires bigint NOT NULL,streak integer NOT NULL DEFAULT 1);
CREATE INDEX ON linkdid.metrics(profile,kind);
CREATE INDEX ON linkdid.notifications(owner,created);
CREATE INDEX ON linkdid.bids(profile);
CREATE INDEX ON linkdid.bids(created);
CREATE INDEX ON linkdid.orders(owner,created);
CREATE INDEX ON linkdid.orders(profile);
CREATE INDEX ON linkdid.paid_bids(profile);
CREATE INDEX ON linkdid.tickets(owner,created);
CREATE INDEX ON linkdid.claims(profile,id);
CREATE INDEX ON linkdid.claims(expires,id);
ALTER TABLE linkdid.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE linkdid.gas_tanks ENABLE ROW LEVEL SECURITY;
ALTER TABLE linkdid.metrics ENABLE ROW LEVEL SECURITY;
ALTER TABLE linkdid.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE linkdid.bids ENABLE ROW LEVEL SECURITY;
ALTER TABLE linkdid.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE linkdid.paid_bids ENABLE ROW LEVEL SECURITY;
ALTER TABLE linkdid.tickets ENABLE ROW LEVEL SECURITY;
ALTER TABLE linkdid.claims ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA linkdid FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA linkdid FROM PUBLIC, anon, authenticated;
-- Private tables are reached only by the authenticated server API. No arbitrary SQL RPC.
INSERT INTO storage.buckets (id,name,public,file_size_limit,allowed_mime_types)
VALUES ('profile-photos','profile-photos',false,2097152,ARRAY['image/png','image/jpeg','image/webp']) ON CONFLICT(id) DO NOTHING;
